      for (const a of anns) {
        begin = a.begin_ts.isAfter(begin) ? a.begin_ts : begin;
        end = a.end_ts.isBefore(end) ? a.end_ts : end;
        labels.push(...a.labels);
        notes += a.notes;
        id += a.id;
      }
      result = Info.newAnnotation(id, begin, end, notes, labels);
