function importJSON(json) {
    const data = JSON.parse(json);
    if (data != null && data != undefined) {
        return cleanAndAddCalculatedFields(data);
    }
    return null;
}

function importRaceInfoJSON(json) {
    const data = JSON.parse(json);
    return cleanRaceInfoData(data);
}

async function parseNmeaData(text, notifyFn = null) {
    let timeFrames;
    let aisTracks;
    [timeFrames, aisTracks] = await _parseNmeaDataToTimeframes(text, notifyFn);
    timeFrames = rollingAverage(timeFrames, 1, 3);
    const records = findRecords(timeFrames);
    
    const aisArr = [];
    for(const mmsi in aisTracks) {
        const track = aisTracks[mmsi];
        const aisRecords = findRecords(track.data);
        track.records = aisRecords;
        aisArr.push(track);
    }
    aisArr.sort((a,b) => b.data.length - a.data.length);
    
    const data = {
        vessel: {
            shipName: "",
            data: timeFrames,
            records: records
        },
        ais: aisArr
    };
    return cleanAndAddCalculatedFields(data);
}

async function _parseNmeaDataToTimeframes(text, notifyFn = null) {
    const lines = text.split('\n');
    let timeFrames = [];
    let oldTime = null;
    let currentRawFrame = createEmptyRawFrame();
    let aisTracks = {};
    const optionalDataFunctions = dataFunctionList(lines);
    let startTime = null;
    let oldHour = 0;
    for (const line of lines) {
        const trimmedLine = line.trim();
        if (!validateChecksum(line)) {
            console.log("invalid checksum NMEA data:",line);
            continue;
        }
        const newTime = storePosition(trimmedLine, currentRawFrame, oldTime);
        if (newTime != null) {
            if (currentRawFrame.t == null) {
                currentRawFrame.t = newTime;
            } else if (newTime != null && newTime.isAfter(currentRawFrame.t)){
                timeFrames.push(...createTimeFrames(currentRawFrame, newTime));
                currentRawFrame = createEmptyRawFrame();
            }
            oldTime = newTime;
            const newHour = Math.floor(newTime.valueOf() / 3600000);
            if (newHour != oldHour) {
                startTime = startTime == null ? newTime : startTime;
                const hours = newTime.diff(startTime, 'hours') ;
                if (!Number.isNaN(hours)) {
                    if (notifyFn != null)
                        await notifyFn('Hours on the rail: ' + hours);
                    oldHour = newHour;
                }
            }
        }
        // }
        try {
            storeAisSentence(trimmedLine, aisTracks, oldTime);
            storeSpeedFromVHW(trimmedLine, currentRawFrame);
            storeWindFromMWV(trimmedLine, currentRawFrame);
            // storeHeadingFromHDT(trimmedLine, currentRawFrame);
            storeOrientationFromXDR(trimmedLine, currentRawFrame);
            for(const fn of optionalDataFunctions) {
                fn(trimmedLine, currentRawFrame);
            }
        } catch (e) {
        console.warn("Error parsing line:", trimmedLine, e);
        } 
    }
    // console.log(summarizeAisTracks(aisTracks));
    // console.log("frames:", timeFrames);
    timeFrames = removeImpossibleData(timeFrames);
    // console.log(timeFrames);
    return [timeFrames, aisTracks];
}

function isInvalid(frame, field) {
    if (frame != null) {
        return frame[field] == undefined && frame[field] == null;
    }
    return true;
}
function maxAbs(frame, oldFrame, field) {
    if (isInvalid(oldFrame,field))
        return isInvalid(frame,field) ? null : frame;
    else if (!isInvalid(frame, field) && Math.abs(frame[field]) > Math.abs(oldFrame[field]))
        return frame;
    else 
        return oldFrame;
}
function findRecords(frames) {
    if (frames != null && frames.length > 0) {
        let maxBsFrame = null;
        let maxSogFrame = null;
        let maxRollFrame = null;
        let maxWindSpdFrame = null;
        frames.forEach(f => {
            maxBsFrame = maxAbs(f, maxBsFrame, 'bs');
            maxSogFrame = maxAbs(f, maxSogFrame, 'sog');
            maxRollFrame = maxAbs(f, maxRollFrame, 'p');
            maxWindSpdFrame = maxAbs(f, maxWindSpdFrame, 'tws');
        });
        return {
            maxBs: maxBsFrame,
            maxSog: maxSogFrame,
            maxR: maxRollFrame,
            maxTws: maxWindSpdFrame,
        };
    }
    return {};
}

// ############################################### utilities ###################################################
function convert360North0To180PosNeg(angleDeg) {
    if (angleDeg > 180) {
        angleDeg = (angleDeg%360 - 180) - 180;
    }
    return parseInt(angleDeg);
}

function getBearingLonLat(lon1, lat1, lon2, lat2) {
    const b = bearing(point([lon1, lat1]), point([lon2, lat2]));
    return (b + 360) % 360;
}

function getBearingFrames(f1, f2) {
    return getBearingLonLat(f1.lon, f1.lat, f2.lon, f2.lat);
}

function bearingDelta(from, to, accessFn = (e) => {return e;}) {
    return (accessFn(to) - accessFn(from) + 540) % 360 - 180;
}

//average by extracting deltas.
function averageAngle(angles, accessFn = (e) => {return e;}) {
    if (angles == null) return NaN;
    if (angles.length === 0) return NaN;
    if (angles.length === 1) return angles[0];
    angles = angles.filter(a => Number.isFinite(accessFn(a)));
    if (angles.length > 0) {
        const from = angles[0];
        let deltas = angles.map(to => bearingDelta(from, to, accessFn));
        const avgDelta = deltas.reduce((acc, b) => acc + b) / deltas.length;
        let avg = accessFn(from) + avgDelta;
        avg = (avg % 360 + 360) % 360;
        return parseInt(avg);
    } else {
        return NaN;
    }
}

function averageValue(values, dp, accessFn = (e) => {return e;}) {
    if (!values || values.length === 0) return null;
    let avg = 0;
    let len = values.length;
    for(let i=0;i<values.length;i++) {
        const val = parseFloat(accessFn(values[i]));
        if (Number.isFinite(val)) {
            avg+= val;
        } else {
            len--;
        }
    }
    avg = avg / len;
    if (dp != null) {
        avg = parseFloat(avg.toFixed(dp));
    }
    return avg;
}

function calculateTrueWind(boatSpeed, awaDeg, aws) {
    const awaRad = awaDeg * Math.PI / 180;
    const wx = aws * Math.sin(awaRad);
    const wy = aws * Math.cos(awaRad);

    // True wind vector = apparent wind vector + (-boat speed vector)
    const twx = wx;
    const twy = wy - boatSpeed;

    // True wind speed and angle (relative to bow)
    const tws = Math.sqrt(twx * twx + twy * twy);
    let twa = Math.atan2(twx, twy) * 180 / Math.PI;
    if (twa < 0) twa += 360;

    return {
        tws: parseFloat(tws.toFixed(2)),
        twa: parseFloat(twa.toFixed(0))
    };
}

function projectVector(angleDeg, distance, projectAngleDeg) {
    const angleDiff = ((angleDeg - projectAngleDeg + 540) % 360) - 180; // Range [-180, 180]
    const projected = distance * Math.cos(angleDiff * Math.PI / 180);
    return projected;
}

