function cleanAndAddCalculatedFields(data) {
    if (data == null || data.vessel == null || data.vessel.data == null) {
        alert('bad data file!');
        return null;
    }
    for(let i=data.vessel.data.length-1;i>=0;i--){
        const f = data.vessel.data[i];
        if (!cleanFrame(f)){
            data.vessel.datas.splice(i,1);
            continue;
        }
        if (i > 0) {
            f._cog = parseInt(getBearingFrames(data.vessel.data[i-1],f));
            if (f.twa == null || isNaN(f.twa)) {
                const tw = calculateTrueWind(f.bs, f.awa, f.aws);
                f.twa = tw.twa;
                f.tws = tw.tws;
            }
            if (f.twa != null && f.twa != undefined) {
                f._twd = parseInt((f._cog + f.twa) % 360);
                f._awd = parseInt((f._cog + f.awa) % 360);
                f._vmg = parseFloat(projectVector(f._cog, f.bs, f._twd).toFixed(2));
                const windCourseDiffDeg = Math.abs(bearingDelta(f._twd, f._cog));
                if (windCourseDiffDeg > 90) {
                    f._vmg = -1 * f._vmg;
                }
            }
        }
        if (data.vessel.records) {
            cleanFrame(data.vessel.records.maxBs);
            cleanFrame(data.vessel.records.maxSog);
            cleanFrame(data.vessel.records.maxR);
            cleanFrame(data.vessel.records.maxTws);
        }
    }    if (data.ais) {
        for(const aisData of data.ais) {
            if (aisData.data != undefined && aisData.data.length > 0) {
                for(let i=aisData.data.length-1;i>=0;i--){
                    const f = aisData.data[i];
                    if (!cleanFrame(f)) {
                        aisData.data.splice(i,1);
                        continue;
                    }
                    if (f.sog > 50 || Math.abs(f.lat) > 90 || Math.abs(f.lon) > 180 ) {
                        console.log("removed impossible ais data:",f);
                        aisData.data.splice(i,1);
                        continue;
                    }
                    if (i > 0) {
                        f._cog = getBearingFrames(aisData.data[i-1],f);
                    }
                    cleanFrame(aisData.records.maxSog);
                }            }
        }
    }
    // console.log("data:", data);
    return data;
}

function cleanRaceInfoData(data) {
    if (data == null) {
        return Info.getEmptyRaceInfo();
    }
    if (data.annotations != undefined && data.annotations != null) {
        for (let i = data.annotations.length - 1; i >= 0; i--) {
            const f = data.annotations[i];
            const begin_ts = hooks(f.begin_ts);
            const end_ts = hooks(f.end_ts);
            if (begin_ts.isValid() && end_ts.isValid()) {
                f.begin_ts = begin_ts;
                f.end_ts = end_ts;
                if (f.id == undefined || f.id == null) {
                    f.id = i;
                }
            } else {
                console.log("invalid data in annotations", f);
                data.annotations.splice(i, 1);
            }
        }
    } else {
        data.annotations = [];
    }
    console.log("data:", data);
    return data;
}

function cleanFrame(f) {
    if (f == null)
        return false;
    f.t = hooks(f.t);
    if (!f.t.isValid()) {
        console.error("invalid data in frame", f);
        return false;
    }
    if (f.lat === undefined || f.lat == null || Number.isNaN(f.lat)) {
        console.error("problem with lat", f);
        return false;
    }
    if (f.lon === undefined || f.lon == null || Number.isNaN(f.lon)) {
        console.error("problem with lon", f);
        return false;
    }

    cleanDataPoint(f, 'twa');
    cleanDataPoint(f, 'tws');
    cleanDataPoint(f, 'sog');
    cleanDataPoint(f, 'cog');
    cleanDataPoint(f, 'bs');
    cleanDataPoint(f, 'th');
    cleanDataPoint(f, 'awa');
    cleanDataPoint(f, 'aws');
    cleanDataPoint(f, 'p');
    cleanDataPoint(f, 'r');
    return true;
}

function cleanDataPoint(f,field) {
    if (f[field] !== undefined || f[field] != null) {
        f[field] = parseFloat(f[field]);
    }
}

/**
 * Interpolates AIS data for each ship in the ais array at 1-second intervals.
 * For each ship, replaces its data array with interpolated points for t, lat, lon, sog, th.
 * @param {Object} data - The main data object containing ais array.
 */
function interpolateAIS(data) {
    if (!data || !Array.isArray(data.ais)) return;

    data.ais.forEach(ship => {
        const original = ship.data;
        if (!original || original.length < 2) return;

        let interpolated = [];
        for (let i = 0; i < original.length - 1; i++) {
            const a = original[i];
            const b = original[i + 1];

            // Ensure valid times
            const tA = typeof a.t === 'object' && a.t.isValid ? a.t : hooks(a.t);
            const tB = typeof b.t === 'object' && b.t.isValid ? b.t : hooks(b.t);
            const dt = tB.diff(tA, 'seconds');

            if (dt < 1) continue;

            for (let s = 0; s < dt; s++) {
                const frac = s / dt;
                if (s === 0) {
                    interpolated.push(a);
                } else {
                    const lon = a.lon + frac * (b.lon - a.lon);
                    const lat = a.lat + frac * (b.lat - a.lat);
                    const last = interpolated[interpolated.length-1];
                    const _cog = getBearingLonLat(last.lon, last.lat, lon, lat);
                    interpolated.push({
                        t: tA.clone().add(s, 'seconds'),
                        lat: lat,
                        lon: lon,
                        sog: a.sog + frac * (b.sog - a.sog),
                        cog: a.cog + frac * (bearingDelta(a.cog,b.cog)) % 360,                        
                        _cog: _cog,                        
                        th: a.th,
                        intrp: true
                    });
                }
            }
        }
        interpolated.push(original[original.length - 1]);
        ship.data = interpolated;
    });
    return;
}

/**
 * Interpolates AIS data for each ship in the ais array at 1-second intervals.
 * For each ship, replaces its data array with interpolated points for t, lat, lon, sog, th.
 * @param {Object} data - The main data object containing ais array.
 */
function pruneInterpolatedAIS(data) {
    if (!data || !Array.isArray(data.ais)) return;

    data.ais.forEach(ship => {
        const original = ship.data;
        if (!original || original.length < 2) return;
        for (let i = original.length-1; i >=0 ; i--) {
            if (original[i].intrp == true) {
                original.splice(i,1);
            }
        }
    });
}





