function createEmptyRawFrame() {
    return {t:null, lat:[], lon:[], tws:[], twa:[], bs:[], sog:[], th: [], awa: [], aws: [], p: [], r: []};
}





function createEmptyTimeFrame(t, twa, tws, bs, lat, lon, sog, th, awa, aws, pitch, roll) {
    return { t: t, 
            twa: twa, 
            tws: tws, 
            bs: bs, 
            lat: lat, 
            lon: lon, 
            sog: sog, 
            th: th, 
            awa: awa, 
            aws: aws,
            p: pitch,
            r: roll
        };
}

function createTimeFrames(rawFrame, newTime) {
    const timeFrames = [];
    const maxItems = Math.max(rawFrame.tws.length,rawFrame.twa.length,rawFrame.bs.length, rawFrame.lat.length,rawFrame.lon.length, rawFrame.sog.length, rawFrame.th.length);
    const deltaMs = newTime.diff(rawFrame.t);
    for (let i = 0; i < maxItems; i++) {
        let frameTime = hooks(rawFrame.t);
        frameTime.add(deltaMs/maxItems*i,'ms');
        let frame = createEmptyTimeFrame(
            frameTime,
            rawFrame.twa[Math.floor(i*rawFrame.twa.length/maxItems)],
            rawFrame.tws[Math.floor(i*rawFrame.tws.length/maxItems)],
            rawFrame.bs[Math.floor(i*rawFrame.bs.length/maxItems)],
            rawFrame.lat[Math.floor(i*rawFrame.lat.length/maxItems)],
            rawFrame.lon[Math.floor(i*rawFrame.lon.length/maxItems)],
            rawFrame.sog[Math.floor(i*rawFrame.sog.length/maxItems)],
            rawFrame.th[Math.floor(i*rawFrame.th.length/maxItems)],
            rawFrame.awa[Math.floor(i*rawFrame.awa.length/maxItems)],
            rawFrame.aws[Math.floor(i*rawFrame.aws.length/maxItems)],
            rawFrame.p[Math.floor(i*rawFrame.p.length/maxItems)],
            rawFrame.r[Math.floor(i*rawFrame.r.length/maxItems)]
            
        );

        
        timeFrames.push(frame);
    }
    // console.log("frame", timeFrames);
    return timeFrames
}


