    const avgCompletionTwaCentered = convert360North0To180PosNeg(completionTwaAngles);

    if (Maneuvers.checkCrossingCenteredTWA(currAvgTwaCentered, avgCompletionTwaCentered)){
      console.log("went back to other side - skipping");
      return null;
    }

    const lastManeuverFinish = this.list.length > 0 ? this.list[this.list.length - 1].completionFrame.t : null;
    return Maneuver.create(prevAvgTwaCentered, currAvgTwaCentered, frames, crossingIdx, finishIdx, completionIdx, lastManeuverFinish);
