const BOAT_COLORS_ARR = ["#000000", ...chroma.brewer.Set1, "#92c8ffff", "#942eb6ff", "#2eb672ff", "#e6a582ff"];

class Race {

  constructor(sail, info) {
    this._sail = sail;
    this._info = info;
    this._raceTracks = null;
    this.startPointCache = null;
  }

  getRaceTracks() {
    return this._raceTracks;
  }

  buildRaceTracks() {
    try {
      const course = this._info.getCourse();
      if (!course) return null;
      console.log("Race.buildRaceTracks - creating NEW RaceTracksN instance");
      this._raceTracks = new RaceTracksN(this._sail, this._info);
      this._raceTracks.calcRacePositions();
      console.log("Race.buildRaceTracks - new instance ID:", this._raceTracks._instanceId, "courseLegs:", this._raceTracks.courseLegs?.length);
      return this._raceTracks;
    } catch (e) {
      console.log("error building race tracks:", e);
    }
    return null;
  }

  setFileNames(fileName) {
    this._sail.raceFileName = fileName;
    this._info.fileName = Info.infoFileNameFor(fileName);
  }

  info() {
    return this._info;
  }

  sail() {
    return this._sail;
  }

  getStartPoint() {
    if (this.startPointCache != null)
      return this.startPointCache;

    let startPoint = this._sail.getStartPoint();
    if (startPoint == null) {
      startPoint = this._info.getCourseStartTime();
      if (startPoint != null) {
        startPoint = startPoint.clone().subtract(5, 'minutes');
      }
    }
    this.startPointCache = startPoint;
    return startPoint;
  }

  static async loadFromNMEA(text, fileName, notifyFn = null, settings = null) {
    const sailingData = await parseNmeaData(text, notifyFn);
    // bd.interpolateAIS(sailingData);
    const race = new Sail(sailingData, fileName, null);
    race.calculateFields(settings);
    const raceInfo = new Info(null, Info.infoFileNameFor(fileName), null);
    return new Race(race, raceInfo);
  }

}

