function skewedNormalize(x, min = 1, max = 20, power = 3) {
    let t = (x - min) / (max - min);
    return Math.pow(t, power);
}

function inverseSkewedNormalize(y, min = 1, max = 20, power = 3) {
    const t = Math.pow(y, 1 / power);
    return min + t * (max - min);
}

