function generatePolarTracesFromTimeframes(timeframes, halfPolar) {
  const speedBins = {};
  for (const f of timeframes) {
    const spdBin = binValueWindSpd(f.tws);
    let b = speedBins[String(spdBin)];
    if (b == undefined) {
      b = [];
      speedBins[String(spdBin)] = b;
    }

    b.push(f);
  }
  const speedBinArr = [];
  Object.keys(speedBins).forEach(b => {
    speedBinArr.push(b);
  });
  const sortedSpdBins = [...speedBinArr].sort((a, b) => parseInt(a) - parseInt(b));
  
  const traces = [];
  sortedSpdBins.forEach(b => {
    const theta = [];
    const r = [];
    const timestamps = [];
    const frames = speedBins[String(b)];
    for (const f of frames) {
      let angle = f.twa;
      if (halfPolar && f.twa > 180)
        angle = (360 - f.twa);
      theta.push(angle);
      r.push(f.bs);
      timestamps.push(f.t);
    }
    
    traces.push({
      type: "scatterpolar",
      mode: "markers",
      name: `TWS ${b} kn`,
      theta: theta,
      r: r,
      customdata: timestamps,
      opacity: 0.4,
      marker: { color: getColorForWind(b)}
    });
  });

  return traces;
}


