    showDotsOnPolar:false,
    polar:null,
    raceTimeframes: null,
    polarFileId:null,
    _polarfileCache: new Map(),
    selectedPolarName: null,
    showingPolarFile: false,
    overlayPolar: null,

    init: async function() {
        if (!this._init) {
            await ensurePolarFolderAsync();
            this._init = true;
            return false;
        }
        return this._init;
    },
    setSelectedPolarName: function(name) {
        this.selectedPolarName = name;
    },
