/***************************************** POLAR SEGMENT MAP ******************************************/

function showTrack(vessel, annotation) {
    const coords = vessel.data.map(f => [f.lon, f.lat]);
    const layers = [
        new PathLayer$1({
            id: 'track',
            data: [{ path: coords }],
            getPath: d => d.path,
            getColor: [128, 128, 128],
            getWidth: 2,
            widthMinPixels: 2
        })
    ];
    
    if (annotation) {
        const highlightCoords = sliceCoordsForAnnotation(vessel.data, annotation);
        if (highlightCoords) {
            layers.push(new PathLayer$1({
                id: 'highlight',
                data: [{ path: highlightCoords }],
                getPath: d => d.path,
                getColor: [255, 0, 0],
                getWidth: 2,
                widthMinPixels: 2
            }));
        }
    }
    
    overlay.setProps({ layers });
    
    setTimeout(() => {
        const bounds = coords.reduce((b, c) => {
            b[0] = Math.min(b[0], c[0]);
            b[1] = Math.min(b[1], c[1]);
            b[2] = Math.max(b[2], c[0]);
            b[3] = Math.max(b[3], c[1]);
            return b;
        }, [Infinity, Infinity, -Infinity, -Infinity]);
        map.fitBounds(bounds, { padding: 40 });
    }, 200);
}

function sliceTimeframesBy(timeframes, annotation) {
    const startIdx = timeframes.findIndex(x => x.t.isSameOrAfter(annotation.begin_ts));
    const endIdx = timeframes.findIndex(x => x.t.isSameOrAfter(annotation.end_ts));
    if (startIdx >= 0 && endIdx >= 0) {
        return timeframes.slice(startIdx,endIdx+1);
    }
    return null;
}

function sliceCoordsForAnnotation(data, annotation) {
    const startIdx = data.findIndex(x => x.t.isSameOrAfter(annotation.begin_ts));
    const endIdx = data.findIndex(x => x.t.isSameOrAfter(annotation.end_ts));
    if (startIdx >= 0 && endIdx >= 0) {
        return data.slice(startIdx, endIdx + 1).map(f => [f.lon, f.lat]);
    }
    return null;
}

