function startPlayerWithRace(race) {
  if (race.sail().getTracks().length == 0) {
    return;
  }
  const vesselTrack = race.sail().getVesselTrack();

  if (vesselTrack.getShipName() == null || vesselTrack.getShipName() == "") {
    vesselTrack.setShipName(localStorage.getItem(LOCAL_STORAGE.SHIPNAME));
  }
  createAnnotationsDisplay();
  
  const map = getMap();
  initCourseCreator(race, map);
  initTrackEditor(race, map);
  
  const settings = dataStore.getSettings();
  mainBoatList = new MainBoatList(dataStore, mapplayer, settings);
  mainBoatList.init();

  const course = race.info().getCourse();
  if (course) {
    race.buildRaceTracks();
    const raceTracks = race.getRaceTracks();
    mainBoatList.setRaceTracksN(raceTracks);
    console.log(race.info().prettyPrintCourse());
    //TODO at this point setCurrentPlayTime is called but it could be returned and set out hear, more clear
    courseCreator.loadCourse();
    courseCreator.displayCourse();
  } else {
    courseCreator.clearCourse();
  }

  mainBoatList.createLegend();

  initMap(postAnimateHook, race, settings);
}

function initCourseCreator(race, map) {
  if (courseCreator) {
    courseCreator.deactivate();
  }
  courseCreator = new CourseCreator(map, race.info(), (info) => {
    console.log(stringifyWithMaxDepth(info.getCourse()));
    raceData().buildRaceTracks();
    const raceTracks = raceData().getRaceTracks();
    mainBoatList.setRaceTracksN(raceTracks);
    saveRaceInfoDataFileGDriveAsync();
  });
  console.log(stringifyWithMaxDepth(race.info().getCourse()));
  courseCreator.setTrackAnimator({
    getCurrentTime: () => getCurrentPlayTime(),
    setCurrentPlayTime: (ts) => setCurrentPlayTime(ts)
  });
  return map;
}

function initTrackEditor(race, map) {
  if (trackEditor) {
    trackEditor.deactivate();
  }
  const onActivate = () => {
    race.sail().pruneAIS();
    initAnimator();
    disablePlayer(true);
  };

  const onTracksModified = () => {
    race.buildRaceTracks();
    const raceTracks = race.getRaceTracks();
    mainBoatList.setRaceTracksN(raceTracks);
    initAnimator();
  };

  const onSave = async () => {
    await saveDataFileGDriveAsync();
  };

  const onDeactivate = () => {
    race.sail().interpolateAIS();
    race.buildRaceTracks();
    const raceTracks = race.getRaceTracks();
    mainBoatList.setRaceTracksN(raceTracks);
    initAnimator();
    disablePlayer(false);
  };

  trackEditor = new TrackEditor(map, race.sail(), onTracksModified, onSave, onActivate, onDeactivate);
}

