function postAnimateHookImpl() {
  updateAnnotationsDisplay();
  mainBoatList.updateLegendAll();
  const clickHandler = (ts) => { setCurrentPlayTime(ts); };
  //TODO - should we set a new click handler for every frame?
  updatePolarPane(clickHandler, raceData().sail().data.vessel);
}

function postAnimateHook() {
  const ts = Date.now();
  if (_postAnimateLastTs + 250 < ts){
    _postAnimateLastTs = ts;
    postAnimateHookImpl();
    
  } else {
    if (_postAnimatePending) 
      return;
    _postAnimatePending = true;
    setTimeout(() => { 
      _postAnimatePending = false;
      postAnimateHookImpl();
    }, 500);
  }
}

