function setAnnotateEndValue(t) {
  const begin = hooks(document.getElementById("beginTimeInput").value);
  if (!begin.isValid() || begin.isBefore(t)) {
    document.getElementById("endTime").textContent = t.format("DD-MM HH:mm:ss");
    document.getElementById("endTimeInput").value = t.toISOString();
    updateTimeWindow$1(begin, t);
  } else {
    alert("End is before beginning!");
  }
}

function setAnnotateBeginValue(t) {
  const end = hooks(document.getElementById("endTimeInput").value);
  if (!end.isValid() || end.isAfter(t)) {
    document.getElementById("beginTime").textContent = t.format("DD-MM HH:mm:ss");
    document.getElementById("beginTimeInput").value = t.toISOString();
    updateTimeWindow$1(t, end);
  } else {
    alert("End is before beginning!");
  }
}

// controls all the UI state logic about the opening and closing the annotation edit panel
let _weHidPolar = false;
function showAnnotationEditPanel(flag) {
  setButtonEnabled(!flag);
  if (flag && getVisible()) {
    setVisible(false);
    _weHidPolar = true;
  } else if (!flag && _weHidPolar) {
    setVisible(true);
    _weHidPolar = false;
  }
  const annotationsPanel = document.getElementById("annotations");
  annotationsPanel.style.display = flag ? "block" : "none";
  clearAnnotationPanelContent();
  document.getElementById("annotationCloseButton").style.display = _showAllAnnotations ? "none" : "block";
  document.getElementById('annotation-add-control').style.display= flag ? "flex" : "none";
  displayTimeWindow(flag);
}



function clearAnnotationPanelContent() {
  document.getElementById('beginTime').textContent = "   ...   ";
  document.getElementById('beginTimeInput').value = "";
  document.getElementById('endTime').textContent = "   ...   ";
  document.getElementById('endTimeInput').value = "";
  document.getElementById('label1').value = "";
  document.getElementById('label2').value = "";
  document.getElementById('notes').value = "";
  document.getElementById('annotationEditedId').value = "";
  clearTimeWindow();
}

function openAnnotationEditPanel(id) {
  showAnnotationEditPanel(true);
  const annotationsPanel = document.getElementById("annotations");
  annotationsPanel.style.display = "block";
  const foundIdx = raceData().info().getAnnotations().findIndex((x) => parseInt(x.id) == id);
  if (foundIdx >= 0) {
    const a = raceData().info().getAnnotations()[foundIdx];
    _annotationEditing = a;
    setAnnotateBeginValue(hooks(a.begin_ts));
    setAnnotateEndValue(hooks(a.end_ts));
    if (a.labels.length > 0)
      document.getElementById('label1').value = a.labels[0];
      if (a.labels.length > 1)  
        document.getElementById('label2').value = a.labels[1];
    document.getElementById('notes').value = a.notes;
    document.getElementById('annotationEditedId').value = a.id;
  }
}



let _showAllAnnotations = false;
function updateAnnotationsDisplay() {
  if (window.innerWidth < 768 || dataStore.isSharedFileMode())
    return;
  if (raceData().sail().getTracks().length > 0) {
    const playTime = getCurrentPlayTime();
    const annotations = raceData().info().getAnnotations();
    if (annotations != null) {
      for (let i = 0; i < annotations.length; i++) {
        const a = annotations[i];
        if (_showAllAnnotations || (a.begin_ts.isBefore(playTime) && a.end_ts.isAfter(playTime))) {
          showAnnotationDisplay(a);
        } else {
          hideAnnotationDisplay(a);
        }
      }
    }
  }
}

function createAnnotationsDisplay() {
  if (window.innerWidth < 768 || dataStore.isSharedFileMode())
    return;
  
  raceNotes.value = raceData().info().info.raceNotes;
  document.getElementById("annotationsDisplay").innerHTML = '';
  const annDisplayDiv = document.getElementById('annotationsDisplay');
  for (let i = 0; i < raceData().info().getAnnotations().length; i++) {
      const d = createAnnotationElementsDisplay(raceData().info().getAnnotations()[i]);
      annDisplayDiv.appendChild(d);
  }
}


function hideAnnotationDisplay(a) {
  const ann = document.getElementById(a.id);
  ann.style.display = 'none';
}

function showAnnotationDisplay(a) {
  const ann = document.getElementById(a.id);
  ann.style.display = 'flex';
}

function createAnnotationLabel(labelVal) {
  let l = document.createElement('div');
  l.className = 'annotation-label-display';
  l.innerHTML = labelVal;
  l.style.display = labelVal == "" ? "none":"flex";
  return l;
}

function createAnnotationElementsDisplay(a) {
  const rowGroup = document.createElement('div');
  rowGroup.className = 'annotation-row-display';
  rowGroup.id = a.id;
  if (a.labels != null) {
    a.labels.forEach((labelVal) => {
      rowGroup.appendChild(createAnnotationLabel(labelVal));
    });
  }
  if (a.notes != null) {
    const n = document.createElement('div');
    n.className = 'annotation-note-display';
    n.innerHTML = a.notes;
    n.style.display = a.notes == "" ? "none":"flex";
    rowGroup.appendChild(n);
  }
  const b = document.createElement('button');
  b.className = "icon-button";
  b.id = "labelEditButton";
  b.value = a.id;
  b.innerHTML = "<img class='annotation-button-edit' title='Edit annotation' src='icons/edit.svg'/>";
  b.addEventListener("click", (e) => {
    clearAnnotationEditButtonSelect();
    openAnnotationEditPanel(a.id);
    b.classList.add('selected');
  });
  rowGroup.appendChild(b);
  return rowGroup;
}

function clearAnnotationEditButtonSelect() {
  const annDis = document.getElementById("annotationsDisplay");
  const editButtons = annDis.querySelectorAll('button#labelEditButton');
  for (const otherB of editButtons) {
    otherB.classList.remove('selected');  
  }
  _annotationEditing = null;
}

document.getElementById("annotationAddButton").addEventListener("click", () => {
  clearAnnotationEditButtonSelect();
  showAnnotationEditPanel(true);
});

const playerModeButtonPlayer = document.getElementById("playerModeButtonPlayer");
const playerModeButtonPolar = document.getElementById("playerModeButtonPolar");
const playerModeButtonSettings = document.getElementById("playerModeButtonSettings");
const playerModeButtonHelp = document.getElementById("playerModeButtonHelp");

playerModeButtonPolar.disabled = true;
playerModeButtonSettings.disabled = true;

playerModeButtonPlayer.addEventListener("click", () => {
  showPlayerView('player');
});

playerModeButtonPolar.addEventListener("click", () => {
  showPlayerView('polar');
});

playerModeButtonSettings.addEventListener("click", () => {
  showPlayerView('settings');
});

playerModeButtonHelp.addEventListener("click", () => {
  showPlayerView('help');
});

function showPlayerView(mode) {
  playerModeButtonPlayer.classList.toggle("selected", mode === 'player');
  playerModeButtonPolar.classList.toggle("selected", mode === 'polar');
  playerModeButtonSettings.classList.toggle("selected", mode === 'settings');
  playerModeButtonHelp.classList.toggle("selected", mode === 'help');
  
  document.getElementById("polar-builder").style.display = "none";
  document.getElementById("map-player").style.display = "none";
  document.getElementById("settings-view").style.display = "none";
  document.getElementById("help-viewer").style.display = "none";
  
  if (mode === 'player') {
    document.getElementById("map-player").style.display = "flex";
    updateSize();
    // Refresh boat list to pick up any settings changes
    if (mainBoatList && dataStore.getRace()) {
      mainBoatList.createLegend();
    }
  } else if (mode === 'polar') {
    document.getElementById("polar-builder").style.display = "grid";
    showAsync();
    showToast('Select a race section or a polar file to begin');
  } else if (mode === 'settings') {
    document.getElementById("settings-view").style.display = "block";
    mainSettingsPage.updateDisplay();
  } else if (mode === 'help') {
    document.getElementById("help-viewer").style.display = "block";
    showHelp();
  }
}
